CLASS_RW = {
    "Cassava Bacterial Blight (CBB)": "Indwara ya bagiteri y'imyumbati (CBB)",
    "Cassava Brown Streak Disease (CBSD)": "Indwara ya CBSD y'imyumbati (CBSD)",
    "Cassava Green Mottle (CGM)": "Virusi itera ibibara bibisi ku mababi (CGM)",
    "Cassava Mosaic Disease (CMD)": "Indwara ya mosaic y'imyumbati (CMD)",
    "Healthy cassava leaf": "Ikibabi cy'imyumbati kizima",
}


def tr(text: str, language: str = "en", **values) -> str:
    translated = TEXT.get(text, {}).get(language, text)
    return translated.format(**values) if values else translated


def crop_label(crop: str, language: str) -> str:
    return CROP_RW.get(crop, crop) if language == "rw" else crop


def class_label(name: str, language: str) -> str:
    return CLASS_RW.get(name, name) if language == "rw" else name
